node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

const orderId = '#W4705780';
const itemIds = ['9716794911', '5610875649'];
const newItemIds = ['2364909101', '7389318502'];
const paymentMethodId = 'paypal_5098475';

// Verify order is pending
const order = db.prepare('SELECT * FROM orders WHERE order_id = ?').get(orderId);
if (order.status !== 'pending') throw new Error('Order is not pending');

// Get current order items
const orderItems = db.prepare('SELECT * FROM order_items WHERE order_id = ?').all(orderId);

// Calculate price difference and get new variant details
let diffPrice = 0;
const updates = [];

for (let i = 0; i < itemIds.length; i++) {
  const oldItemId = itemIds[i];
  const newItemId = newItemIds[i];

  // Find the order item
  const oi = orderItems.find(x => x.item_id === oldItemId);
  if (!oi) throw new Error('Item ' + oldItemId + ' not found in order');

  // Get new variant
  const newVariant = db.prepare('SELECT * FROM rt_variants WHERE item_id = ?').get(newItemId);
  if (!newVariant || !newVariant.available) throw new Error('New variant ' + newItemId + ' not available');

  // Ensure same product
  if (oi.product_id !== newVariant.product_id) throw new Error('Product mismatch');

  diffPrice += newVariant.price - oi.unit_price;
  updates.push({ oiId: oi.oi_id, newItemId, newPrice: newVariant.price, newOptions: newVariant.options });
}

diffPrice = Math.round(diffPrice * 100) / 100;

// Update order items
for (const u of updates) {
  db.prepare('UPDATE order_items SET item_id = ?, unit_price = ?, options = ? WHERE oi_id = ?')
    .run(u.newItemId, u.newPrice, u.newOptions, u.oiId);
}

// Add payment/refund record
const txnType = diffPrice > 0 ? 'payment' : 'refund';
const amount = Math.abs(diffPrice);
db.prepare('INSERT INTO order_payments (order_id, transaction_type, amount, payment_method_id) VALUES (?, ?, ?, ?)')
  .run(orderId, txnType, amount, paymentMethodId);

// Update order status
db.prepare(\"UPDATE orders SET status = 'pending (item modified)' WHERE order_id = ?\").run(orderId);

// Verify results
const updatedOrder = db.prepare('SELECT * FROM orders WHERE order_id = ?').get(orderId);
const updatedItems = db.prepare('SELECT * FROM order_items WHERE order_id = ?').all(orderId);
const updatedPayments = db.prepare('SELECT * FROM order_payments WHERE order_id = ?').all(orderId);

console.log('Order status:', updatedOrder.status);
console.log('');
for (const item of updatedItems) {
  console.log(item.name + ' | item_id: ' + item.item_id + ' | options: ' + item.options + ' | price: $' + item.unit_price);
}
console.log('');
console.log('Payment history:');
for (const p of updatedPayments) {
  console.log('  ' + p.transaction_type + ': $' + p.amount + ' via ' + p.payment_method_id);
}
console.log('');
console.log('Price difference: $' + diffPrice.toFixed(2));
"
